SQL> SELECT
  2  'INSERT INTO CATEGORIES (CATEGORY_ID, CATEGORY_NAME) VALUES (' ||
  3  CATEGORY_ID || ', ''' ||
  4  REPLACE(CATEGORY_NAME,'''','''''') || ''');'
  5  FROM CATEGORIES
  6  ORDER BY CATEGORY_ID;
SQL> SELECT
  2  'INSERT INTO CUSTOMERS (CUSTOMER_ID, CUSTOMER_NAME, EMAIL, PHONE, CITY, STATE, REGISTRATION_DATE) VALUES (' ||
  3  CUSTOMER_ID || ', ' ||
  4  '''' || REPLACE(CUSTOMER_NAME,'''','''''') || ''', ' ||
  5  CASE WHEN EMAIL IS NULL THEN 'NULL' ELSE '''' || REPLACE(EMAIL,'''','''''') || '''' END || ', ' ||
  6  CASE WHEN PHONE IS NULL THEN 'NULL' ELSE '''' || REPLACE(PHONE,'''','''''') || '''' END || ', ' ||
  7  CASE WHEN CITY IS NULL THEN 'NULL' ELSE '''' || REPLACE(CITY,'''','''''') || '''' END || ', ' ||
  8  CASE WHEN STATE IS NULL THEN 'NULL' ELSE '''' || REPLACE(STATE,'''','''''') || '''' END || ', ' ||
  9  CASE WHEN REGISTRATION_DATE IS NULL THEN 'NULL'
 10  ELSE 'TO_DATE(''' || TO_CHAR(REGISTRATION_DATE,'YYYY-MM-DD') || ''',''YYYY-MM-DD'')' END ||
 11  ');'
 12  FROM CUSTOMERS
 13  ORDER BY CUSTOMER_ID;
SQL> SELECT
  2  'INSERT INTO PRODUCTS (PRODUCT_ID, PRODUCT_NAME, CATEGORY_ID, UNIT_PRICE, COST_PRICE, STOCK_QUANTITY) VALUES (' ||
  3  PRODUCT_ID || ', ' ||
  4  '''' || REPLACE(PRODUCT_NAME,'''','''''') || ''', ' ||
  5  NVL(TO_CHAR(CATEGORY_ID), 'NULL') || ', ' ||
  6  NVL(TO_CHAR(UNIT_PRICE,'FM9999999990D00','NLS_NUMERIC_CHARACTERS=''.,'''), 'NULL') || ', ' ||
  7  NVL(TO_CHAR(COST_PRICE,'FM9999999990D00','NLS_NUMERIC_CHARACTERS=''.,'''), 'NULL') || ', ' ||
  8  NVL(TO_CHAR(STOCK_QUANTITY), 'NULL') ||
  9  ');'
 10  FROM PRODUCTS
 11  ORDER BY PRODUCT_ID;
SQL> SELECT
  2  'INSERT INTO ORDERS (ORDER_ID, CUSTOMER_ID, ORDER_DATE, ORDER_STATUS, PAYMENT_METHOD) VALUES (' ||
  3  ORDER_ID || ', ' ||
  4  CUSTOMER_ID || ', ' ||
  5  'TO_DATE(''' || TO_CHAR(ORDER_DATE,'YYYY-MM-DD') || ''',''YYYY-MM-DD''), ' ||
  6  '''' || REPLACE(ORDER_STATUS,'''','''''') || ''', ' ||
  7  '''' || REPLACE(PAYMENT_METHOD,'''','''''') || '''' ||
  8  ');'
  9  FROM ORDERS
 10  ORDER BY ORDER_ID;
SQL> SELECT
  2  'INSERT INTO ORDER_DETAILS (ORDER_DETAIL_ID, ORDER_ID, PRODUCT_ID, QUANTITY, UNIT_PRICE, DISCOUNT_AMOUNT) VALUES (' ||
  3  ORDER_DETAIL_ID || ', ' ||
  4  ORDER_ID || ', ' ||
  5  PRODUCT_ID || ', ' ||
  6  NVL(TO_CHAR(QUANTITY), 'NULL') || ', ' ||
  7  NVL(TO_CHAR(UNIT_PRICE,'FM9999999990D00','NLS_NUMERIC_CHARACTERS=''.,'''), 'NULL') || ', ' ||
  8  NVL(TO_CHAR(DISCOUNT_AMOUNT,'FM9999999990D00','NLS_NUMERIC_CHARACTERS=''.,'''), 'NULL') ||
  9  ');'
 10  FROM ORDER_DETAILS
 11  ORDER BY ORDER_DETAIL_ID;
SQL> SPOOL OFF
